27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "identityKey",
31	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.of(owner))")
32	    @Mapping(target = "telephoneDisplay",
33	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.E164Telephone.display(owner.getTelephone()))")
