35	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
36	    @Mapping(target = "locality", expression = "java(locality(owner))")
37	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
38	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * Derives the owner's salutation: the {@code title} and {@code lastName} separated by a single
44	     * space (e.g. {@code "DR Franklin"}), or just the {@code lastName} when no title was supplied.
45	     */
46	    default String salutation(Owner owner) {
47	        String title = owner.getTitle();
48	        if (title == null || title.isBlank()) {
49	            return owner.getLastName();
50	        }
51	        return title + " " + owner.getLastName();
52	    }
53	
54	    /**
55	     * Derives the owner's age band from {@code birthDate}, computed against the
56	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18-64,
57	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date was supplied
58	     * (or the registration date is absent, e.g. seed data), so the field is simply absent.
59	     */
60	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
61	        java.time.LocalDate birthDate = owner.getBirthDate();
62	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
63	        if (birthDate == null || registrationDate == null) {
64	            return null;
65	        }
66	        int years = java.time.Period.between(birthDate, registrationDate).getYears();
67	        if (years < 18) {
68	            return OwnerDto.AgeBandEnum.MINOR;
69	        }
70	        if (years < 65) {
71	            return OwnerDto.AgeBandEnum.ADULT;
72	        }
73	        return OwnerDto.AgeBandEnum.SENIOR;
74	    }
75	
76	    /**
77	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
78	     * present, otherwise {@code PHONE}.
79	     */
80	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
81	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
82	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
83	    }
84	
85	    /**
86	     * The fixed city-to-region table: any city not listed derives locality {@code UNKNOWN}.
87	     */
88	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
89	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
90	
91	    /**
92	     * The fixed region-to-timezone table: maps a region code to its IANA timezone name. Any region
93	     * not listed (e.g. {@code UNKNOWN}) has no timezone.
94	     */
95	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
96	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
97	
98	    /**
99	     * Derives the owner's IANA timezone from the {@link #locality(Owner) locality/region} via the
100	     * fixed {@link #REGION_TIMEZONE} table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
101	     * QLD-&gt;Australia/Brisbane). Returns {@code null} when the region is not one of these, so the
102	     * field is simply absent.
103	     */
104	    default String timezone(Owner owner) {
105	        return REGION_TIMEZONE.get(locality(owner));
106	    }
107	
108	    /**
109	     * Derives the owner's locality from the region-and-hash identity: the REGION prefix of the
110	     * {@code customerCode} (everything before the first {@code '-'}). This is the same region the
111	     * identity is built from ({@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion},
112	     * postcode range first — NSW 2000-2099, VIC 3000-3099, QLD 4000-4099 — then the city table, then
113	     * {@code UNKNOWN}), so the locality a client reads back always matches the code's region prefix.
114	     * Owners with no {@code customerCode} (e.g. seed data) fall back to deriving the region directly.
115	     */
116	    default String locality(Owner owner) {
117	        String code = owner.getCustomerCode();
118	        if (code != null) {
119	            int dash = code.indexOf('-');
120	            if (dash > 0) {
121	                return code.substring(0, dash);
122	            }
123	        }
124	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.of(owner);
125	    }
126	
127	    /**
128	     * Derives the owner's membership points. Starts at 0; adds 2 when an email address is present;
129	     * adds 1 when the owner has no namesakes ({@code namesakeCount} is 0); adds 2 for a household of
130	     * 3 or more members ({@code householdMemberCount} is 3 or greater); adds 3 when the owner's
131	     * tenure spans more than one elapsed fiscal year. A newly created owner has zero tenure, so a
132	     * new owner never earns the tenure points.
133	     */
134	    default int membershipPoints(Owner owner) {
135	        int householdMemberCount = owner.getHouseholdMemberCount() == null ? 0 : owner.getHouseholdMemberCount();
136	        return membershipPointsForHousehold(owner, householdMemberCount);
137	    }
138	
139	    /**
140	     * As {@link #membershipPoints(Owner)}, but scores the household-of-3-or-more bonus against the
141	     * supplied {@code householdMemberCount} rather than the owner's stored one. Used to evaluate an
142	     * existing household member's points at the household's <em>current</em> size (see
143	     * {@link org.springframework.samples.petclinic.rest.function.owner.HouseholdLevelCap}).
144	     */
145	    default int membershipPointsForHousehold(Owner owner, int householdMemberCount) {
146	        int points = 0;
147	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
148	        if (hasEmail) {
149	            points += 2;
150	        }
151	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
152	        if (noNamesakes) {
153	            points += 1;
154	        }
155	        if (householdMemberCount >= 3) {
156	            points += 2;
157	        }
158	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
159	        if (registrationDate != null
160	                && (fiscalYearOf(java.time.LocalDate.now()) - fiscalYearOf(registrationDate)) > 1) {
161	            points += 3;
162	        }
163	        return points;
164	    }
165	
166	    /**
167	     * Maps the owner's {@link #membershipPoints(Owner) membershipPoints} to a numeric level: 1 for
168	     * 0-1 points, 2 for 2-3 points, 3 for 4-5 points, 4 for 6 or more points.
169	     */
170	    default int membershipLevel(Owner owner) {
171	        return levelForPoints(membershipPoints(owner));
172	    }
173	
174	    /**
175	     * As {@link #membershipLevel(Owner)}, but evaluated with the supplied {@code householdMemberCount}
176	     * (see {@link #membershipPointsForHousehold(Owner, int)}).
177	     */
178	    default int membershipLevelForHousehold(Owner owner, int householdMemberCount) {
179	        return levelForPoints(membershipPointsForHousehold(owner, householdMemberCount));
180	    }
181	
182	    /** Maps membership points to the numeric level band. */
183	    default int levelForPoints(int points) {
184	        if (points <= 1) {
185	            return 1;
186	        }
187	        if (points <= 3) {
188	            return 2;
189	        }
190	        if (points <= 5) {
191	            return 3;
192	        }
193	        return 4;
194	    }
195	
196	    /**
197	     * The fiscal year (1 July - 30 June) that {@code date} falls in, named by the calendar year in
198	     * which it ends: a date in July-December belongs to the fiscal year ending the following
199	     * calendar year, a date in January-June to the fiscal year ending the same calendar year. So
200	     * 2026-08-11 is fiscal year 2027 and 2026-03-11 is fiscal year 2026.
201	     */
202	    default int fiscalYearOf(java.time.LocalDate date) {
203	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
204	    }
205	
206	    /**
207	     * Derives the owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of
208	     * the {@link #fiscalYearOf(java.time.LocalDate) fiscal year} of the business-day-adjusted
209	     * registrationDate (e.g. {@code FY27}). Returns {@code null} when no registration date is present
210	     * (e.g. seed data), so the field is simply absent.
211	     */
212	    default String fiscalYear(Owner owner) {
213	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
214	        if (registrationDate == null) {
215	            return null;
216	        }
217	        return String.format("FY%02d", Math.floorMod(fiscalYearOf(registrationDate), 100));
218	    }
219	
220	    /**
221	     * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
222	     * last two digits of the {@link #fiscalYearOf(java.time.LocalDate) fiscal year} of the
223	     * registrationDate (e.g. {@code LON-SMI-0007-M27}) — the same YY as {@link #fiscalYear(Owner)}.
224	     * Returns {@code null} when either source field is absent, so owners without a customer code or
225	     * registration date (e.g. seed data) simply have no membership number.
226	     */
227	    default String membershipNumber(Owner owner) {
228	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
229	            return null;
230	        }
231	        int yy = Math.floorMod(fiscalYearOf(owner.getRegistrationDate()), 100);
232	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
233	    }
234	
235	    /**
236	     * Computes the owner's Luhn check digit (0-9) over the digits contained in the customerCode.
237	     * Returns {@code null} when the customer code is absent (e.g. seed data).
238	     */
239	    default Integer checkDigit(Owner owner) {
240	        String code = owner.getCustomerCode();
241	        if (code == null) {
242	            return null;
243	        }
244	        int sum = 0;
245	        boolean dbl = true;
246	        for (int i = code.length() - 1; i >= 0; i--) {
247	            char c = code.charAt(i);
248	            if (c < '0' || c > '9') {
249	                continue;
250	            }
251	            int d = c - '0';
252	            if (dbl) {
253	                d *= 2;
254	                if (d > 9) {
255	                    d -= 9;
256	                }
257	            }
258	            sum += d;
259	            dbl = !dbl;
260	        }
261	        return (10 - (sum % 10)) % 10;
262	    }
263	
264	    Owner toOwner(OwnerDto ownerDto);
265	
266	    @Mapping(target = "id", ignore = true)
267	    @Mapping(target = "pets", ignore = true)
268	    Owner toOwner(OwnerFieldsDto ownerDto);
269	
270	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
271	
272	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
273	
